"""Write an evidence-limited recheck; original audit and ACCEPTANCE remain read-only."""
from pathlib import Path
import csv, hashlib, json, re
import yaml

R=Path(__file__).resolve().parents[1]; O=R/'remediation'; W=R.parent
def jsonwrite(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2),encoding='utf-8')
def write(p,x):p.write_text(x.strip()+'\n',encoding='utf-8')
def csvwrite(p,rows):
    with p.open('w',encoding='utf-8-sig',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def dump(p,x):p.write_text(yaml.safe_dump(x,allow_unicode=True,sort_keys=False,width=110),encoding='utf-8')

# Keep fresh catalog verification distinct from the independent audit's historical evidence.
S=json.loads((R/'sources.json').read_text(encoding='utf-8'))
for sid in ('RU-GAD','RU-PANIC','RU-PHOB','RU-DEP'):
    S[sid]['current_guideline_status_evidence']='remediation/catalog_check.json + remediation/current_minzdrav_catalog.json; 2026-10-08; CodeVersion/ApplyStatusCalculated=1'
jsonwrite(R/'sources.json',S)
for folder in ('rules','findings','reference_rules'):
    for p in (R/folder).glob('*.yaml'):
        r=yaml.safe_load(p.read_text(encoding='utf-8'));r['sources']=[S[s['source_id']] for s in r['sources']];dump(p,r)

